import{_ as r,a0 as o,w as h,s as l,I as i,x as a,a1 as t,A as p,ao as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse(`{"title":"在 Ubuntu 上配置高性能的 HHVM 環境 | LCTT x X-CMD","titleTemplate":false,"description":"在 Ubuntu 上配置高性能的 HHVM 環境 | LCTT (201509) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Ubuntu 上配置高性能的 HHVM 環境 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Ubuntu 上配置高性能的 HHVM 環境 | LCTT (201509) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201509/20150901 Setting Up High-Performance 'HHVM' and Nginx or Apache with MariaDB on Debian or Ubuntu","title":"在 Ubuntu 上配置高性能的 HHVM 環境","tag":"201509","desc":""},"relativePath":"201509/20150901 Setting Up High-Performance 'HHVM' and Nginx or Apache with MariaDB on Debian or Ubuntu.md","filePath":"[post].md"}`),d={name:"201509/20150901 Setting Up High-Performance 'HHVM' and Nginx or Apache with MariaDB on Debian or Ubuntu.md"};function c(m,e,g,u,H,x){const n=o("Link");return h(),l("div",null,[e[16]||(e[16]=i("h1",{id:"在-ubuntu-上配置高性能的-hhvm-環境",tabindex:"-1"},[a("在 Ubuntu 上配置高性能的 HHVM 環境 "),i("a",{class:"header-anchor",href:"#在-ubuntu-上配置高性能的-hhvm-環境","aria-label":"Permalink to “在 Ubuntu 上配置高性能的 HHVM 環境”"},"​")],-1)),i("p",null,[e[1]||(e[1]=a("HHVM全稱為 HipHop Virtual Machine，它是一個開源虛擬機，用來運行由 Hack(一種編程語言)和 PHP 開發應用。HHVM 在保證了 PHP 程序員最關注的高靈活性的要求下，通過使用最新的編譯方式來取得了非凡的性能。到目前為止，相對於 PHP + ",-1)),t(n,{href:"http://www.tecmint.com/install-apc-alternative-php-cache-in-rhel-centos-fedora/"},{default:p(()=>[...e[0]||(e[0]=[a("APC (Alternative PHP Cache)",-1)])]),_:1}),e[2]||(e[2]=a(" ，HHVM 為 FaceBook 在 HTTP 請求的吞吐量上提高了9倍的性能，在內存的佔用上，減少了5倍左右的內存佔用。",-1))]),e[17]||(e[17]=s(`<p>同時，HHVM 也可以與基於 FastCGI 的 Web 服務器（如 Nginx 或者 Apache ）協同工作。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Install-HHVM-Nginx-Apache-MariaDB.png" alt="Install HHVM, Nginx and Apache with MariaDB"></p><p><em>安裝 HHVM，Nginx和 Apache 還有 MariaDB</em></p><p>在本教程中，我們一起來配置 Nginx/Apache web 服務器、 資料庫服務器 MariaDB 和 HHVM 。我們將使用 Ubuntu 15.04 (64 位)，因為 HHVM 只能運行在64位系統上。同時，該教程也適用於 Debian 和 Linux Mint。</p><h3 id="第一步-安裝-nginx-或者-apache-服務器" tabindex="-1">第一步: 安裝 Nginx 或者 Apache 服務器 <a class="header-anchor" href="#第一步-安裝-nginx-或者-apache-服務器" aria-label="Permalink to “第一步: 安裝 Nginx 或者 Apache 服務器”">​</a></h3><p>1、首先，先進行一次系統的升級並更新軟件倉庫列表，命令如下</p><pre><code># apt-get update &amp;&amp; apt-get upgrade
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/System-Upgrade.png" alt="System Upgrade"></p><p><em>系統升級</em></p><p>2、 正如我之前説的，HHVM 能和 Nginx 和 Apache 進行集成。所以，究竟使用哪個服務器，這是你的自由，不過，我們會教你如何安裝這兩個服務器。</p><h4 id="安裝-nginx" tabindex="-1">安裝 Nginx <a class="header-anchor" href="#安裝-nginx" aria-label="Permalink to “安裝 Nginx”">​</a></h4><p>我們通過下面的命令安裝 Nginx/Apache 服務器</p><pre><code># apt-get install nginx
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Install-Nginx-Web-Server.png" alt="Install Nginx Web Server"></p><p><em>安裝 Nginx 服務器</em></p><h4 id="安裝-apache" tabindex="-1">安裝 Apache <a class="header-anchor" href="#安裝-apache" aria-label="Permalink to “安裝 Apache”">​</a></h4><pre><code># apt-get install apache2
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Install-Apache-Web-Server.png" alt="Install Apache Web Server"></p><p><em>安裝 Apache 服務器</em></p><p>完成這一步，你能通過以下的鏈接看到 Nginx 或者 Apache 的默認頁面</p><pre><code>http://localhost
或
http://IP-Address
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Nginx-Welcome-Page.png" alt="Nginx Welcome Page"></p><p><em>Nginx 默認頁面</em></p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Apache-Default-Page.png" alt="Apache Default Page"></p><p><em>Apache 默認頁面</em></p><h3 id="第二步-安裝和配置-mariadb" tabindex="-1">第二步: 安裝和配置 MariaDB <a class="header-anchor" href="#第二步-安裝和配置-mariadb" aria-label="Permalink to “第二步: 安裝和配置 MariaDB”">​</a></h3><p>3、 這一步，我們將通過如下命令安裝 MariaDB，它是一個比 MySQL 性能更好的資料庫</p><pre><code># apt-get install mariadb-client mariadb-server
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Install-MariaDB-Database.png" alt="Install MariaDB Database"></p><p><em>安裝 MariaDB</em></p><p>4、 在 MariaDB 成功安裝之後，你可以啓動它，並且設置 root 密碼來保護資料庫:</p><pre><code># systemctl start mysql
# mysql_secure_installation
</code></pre><p>回答以下問題，只需要按下<code>y</code>或者 <code>n</code>並且回車。請確保你仔細的閲讀過説明。</p><pre><code>Enter current password for root (enter for none) = press enter
Set root password? [Y/n] = y
Remove anonymous users[y/n] = y
Disallow root login remotely[y/n] = y
Remove test database and access to it [y/n] = y
Reload privileges tables now[y/n] = y
</code></pre><p>5、 在設置了密碼之後，你就可以登錄 MariaDB 了。</p><pre><code># mysql -u root -p
</code></pre><h3 id="第三步-安裝-hhvm" tabindex="-1">第三步: 安裝 HHVM <a class="header-anchor" href="#第三步-安裝-hhvm" aria-label="Permalink to “第三步: 安裝 HHVM”">​</a></h3><p>6、 在此階段，我們將安裝 HHVM。我們需要添加 HHVM 的倉庫到你的<code>sources.list</code>文件中，然後更新軟件列表。</p><pre><code># wget -O - http://dl.hhvm.com/conf/hhvm.gpg.key | apt-key add -
# echo deb http://dl.hhvm.com/ubuntu DISTRIBUTION_VERSION main | sudo tee /etc/apt/sources.list.d/hhvm.list
# apt-get update
</code></pre><p><strong>重要</strong>：不要忘記用你的 Ubuntu 發行版代號替換上述的 DISTRIBUTION_VERSION (比如：lucid, precise, trusty) 或者是 Debian 的 jessie 或者 wheezy。在 Linux Mint 中也是一樣的，不過只支持 petra。</p><p>添加了 HHVM 倉庫之後，你就可以輕鬆安裝了。</p><pre><code># apt-get install -y hhvm
</code></pre><p>安裝之後，就可以啓動它，但是它並沒有做到開機啓動。可以用如下命令做到開機啓動。</p><pre><code># update-rc.d hhvm defaults
</code></pre><h3 id="第四步-配置-nginx-apache-連接-hhvm" tabindex="-1">第四步: 配置 Nginx/Apache 連接 HHVM <a class="header-anchor" href="#第四步-配置-nginx-apache-連接-hhvm" aria-label="Permalink to “第四步: 配置 Nginx/Apache 連接 HHVM”">​</a></h3><p>7、 現在，nginx/apache 和 HHVM 都已經安裝完成了，並且都獨立運行起來了，所以我們需要對它們進行設置，來讓它們互相關聯。這個關鍵的步驟，就是需要告知 nginx/apache 將所有的 php 文件，都交給 HHVM 進行處理。</p><p>如果你用了 Nginx，請按照如下步驟：</p><p>nginx 的配置文件在 /etc/nginx/sites-available/default， 並且這些配置文件會在 /usr/share/nginx/html 中尋找文件執行，不過，它不知道如何處理 PHP。</p><p>為了確保 Nginx 可以連接 HHVM，我們需要執行所帶的如下腳本。它可以幫助我們正確的配置 Nginx，將 hhvm.conf 放到 上面提到的配置文件 nginx.conf 的頭部。</p><p>這個腳本可以確保 Nginx 可以對 .hh 和 .php 的做正確的處理，並且將它們通過 fastcgi 發送給 HHVM。</p><pre><code># /usr/share/hhvm/install_fastcgi.sh
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Configure-Nginx-for-HHVM.png" alt="Configure Nginx for HHVM"></p><p><em>配置 Nginx、HHVM</em></p><p><strong>重要</strong>: 如果你使用的是 Apache，這裏不需要進行配置。</p><p>8、 接下來，你需要使用 hhvm 來提供 php 的運行環境。</p><pre><code># /usr/bin/update-alternatives --install /usr/bin/php php /usr/bin/hhvm 60
</code></pre><p>以上步驟完成之後，你現在可以啓動並且測試它了。</p><pre><code># systemctl start hhvm
</code></pre><h3 id="第五步-測試-hhvm-和-nginx-apache" tabindex="-1">第五步: 測試 HHVM 和 Nginx/Apache <a class="header-anchor" href="#第五步-測試-hhvm-和-nginx-apache" aria-label="Permalink to “第五步: 測試 HHVM 和 Nginx/Apache”">​</a></h3><p>9、 為了確認 hhvm 是否工作，你需要在 nginx/apache 的文檔根目錄下建立 hello.php。</p><pre><code># nano /usr/share/nginx/html/hello.php       [對於 Nginx]
或
# nano /var/www/html/hello.php               [對於 Nginx 和 Apache]
</code></pre><p>在文件中添加如下代碼:</p><pre><code>&lt;?php
if (defined(&#39;HHVM_VERSION&#39;)) {
    echo &#39;HHVM is working&#39;;
    phpinfo();
} else {
    echo &#39;HHVM is not working&#39;;
}
?&gt;
</code></pre><p>然後訪問如下鏈接，確認自己能否看到 &quot;hello world&quot;</p><pre><code>http://localhost/info.php
或
http://IP-Address/info.php
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/HHVM-Page.png" alt="HHVM Page"></p><p><em>HHVM 頁面</em></p><p>如果 “HHVM” 的頁面出現了，那就説明你成功了。</p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>以上的步驟都是非常簡單的，希望你能覺得這是一篇有用的教程，如果你在以上的步驟中遇到了問題，給我們留一個評論，我們將全力解決。</p><hr>`,71)),i("p",null,[e[4]||(e[4]=a("via: ",-1)),t(n,{href:"http://www.tecmint.com/install-hhvm-and-nginx-apache-with-mariadb-on-debian-ubuntu/"},{default:p(()=>[...e[3]||(e[3]=[a("http://www.tecmint.com/install-hhvm-and-nginx-apache-with-mariadb-on-debian-ubuntu/",-1)])]),_:1})]),i("p",null,[e[8]||(e[8]=a("作者：",-1)),t(n,{href:"http://www.tecmint.com/author/admin/"},{default:p(()=>[...e[5]||(e[5]=[a("Ravi Saive",-1)])]),_:1}),e[9]||(e[9]=a(" 譯者：",-1)),t(n,{href:"https://github.com/MikeCoder"},{default:p(()=>[...e[6]||(e[6]=[a("MikeCoder",-1)])]),_:1}),e[10]||(e[10]=a(" 校對：",-1)),t(n,{href:"https://github.com/wxy"},{default:p(()=>[...e[7]||(e[7]=[a("wxy",-1)])]),_:1})]),i("p",null,[e[13]||(e[13]=a("本文由 ",-1)),t(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...e[11]||(e[11]=[a("LCTT",-1)])]),_:1}),e[14]||(e[14]=a(" 原創編譯，",-1)),t(n,{href:"https://linux.cn/"},{default:p(()=>[...e[12]||(e[12]=[a("Linux中國",-1)])]),_:1}),e[15]||(e[15]=a(" 榮譽推出",-1))])])}const f=r(d,[["render",c]]);export{b as __pageData,f as default};
